/* Interactive, deterministic walkthroughs for the four roadmap packs. */
const esc = (v = '') => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = (n, digits = 0) => Number(n).toLocaleString('en-GB', {minimumFractionDigits:digits, maximumFractionDigits:digits});
const eur = n => `€${fmt(n, 2)}`;
const rm = n => `RM ${fmt(n, 2)}`;
const icon = (name, cls = '') => {
  const paths = {
    arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>', check:'<path d="m5 12 4 4L19 6"/>',
    file:'<path d="M14 3H6a1 1 0 0 0-1 1v16a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1V8zM14 3v6h5M8 13h8m-8 4h5"/>',
    shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',
    box:'<path d="m12 3 9 5-9 5-9-5zM3 8v10l9 4 9-4V8M12 13v9M8 5l9 5"/>',
    wave:'<path d="M2 12h4l3-7 5 14 3-7h5"/>', spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',
    chart:'<path d="M4 3v17h17M7 15l4-5 4 3 5-8"/>', info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',
  };
  return `<svg class="pk-icon ${esc(cls)}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name] || paths.box}</svg>`;
};
const head = (index, title, subtitle, name) => `<div class="pk-heading"><div><div class="pk-kicker">CAPABILITY PACK / 0${index} <span class="badge badge-amber">Walkthrough</span></div><h1>${title}</h1><p>${subtitle}</p></div><div class="pk-heading-icon">${icon(name)}</div></div><div class="pk-demo-note">${icon('info')}<span>Fictional Lumora Wellness data. This interactive walkthrough records sample events; external systems and trained models are not connected.</span></div>`;
const numberField = (name, title, value, {min=0,max=100000,step=1,suffix=''} = {}) => `<label class="field"><span>${title}</span><div class="pk-input-unit"><input name="${name}" type="number" min="${min}" max="${max}" step="${step}" value="${value}" required>${suffix ? `<span>${suffix}</span>` : ''}</div></label>`;
const approverFields = (notes = '') => `<div class="form-row pk-approval-fields"><label class="field"><span>Approver name <span class="pk-required">*</span></span><input name="actor" placeholder="Enter your name" minlength="2" maxlength="80" required autocomplete="off"></label><label class="field"><span>Decision note <span class="pk-required">*</span></span><input name="notes" placeholder="Reason for this sample decision" value="${esc(notes)}" minlength="5" maxlength="300" required autocomplete="off"></label></div>`;
const formFooter = label => `<div class="pk-form-footer"><span>${icon('shield')} Named approval is saved to the sample audit trail.</span><button class="btn btn-primary" type="submit">${label} ${icon('arrow')}</button></div><p class="pk-form-error" role="alert" hidden></p>`;

